return [{
  json: {
    company_en: 'Ufuq Marketing',
    company_ar: 'وكالة أفق للتسويق',
    job_title: 'Digital Marketing Officer · مسؤول/ة تسويق رقمي',
    job_description: 'Plan and run paid social and search campaigns, create bilingual content, and report results to management. Full time, Amman.',

    // Rubric: 5 criteria, each scored 0–5 by the model, and only with a quote from the CV as evidence.
    rubric: [
      { key: 'paid_ads', name: 'Paid ads', guide: '0 none · 3 ran campaigns · 5 managed budgets with measured results (ROAS, CPA)' },
      { key: 'content_social', name: 'Content & social media', guide: '0 none · 3 regular content work · 5 content with measured growth' },
      { key: 'analytics', name: 'Analytics & reporting', guide: '0 none · 3 used GA4 or reports · 5 built dashboards or regular reports for decisions' },
      { key: 'bilingual_writing', name: 'Arabic + English writing', guide: '0 no sign · 3 writes in one language · 5 writes copy in both' },
      { key: 'relevant_experience', name: 'Relevant experience', guide: '0 none · 2 under 1 year or internship · 3 1–2 years · 5 3+ years in marketing roles' },
    ],
    // Out of 25. At or above shortlist_at → shortlist. Below review_at → "not a fit" (a feedback DRAFT is prepared).
    shortlist_at: 17,
    review_at: 11,

    // Sheets (tab name as shown at the bottom of each sheet)
    candidates_sheet_id: 'YOUR_CANDIDATES_SHEET_ID',
    identities_sheet_id: 'YOUR_IDENTITIES_SHEET_ID',
    sheet_tab: 'Untitled',

    // The model is set on the three AI nodes (Google Gemini, n8n free AI credits), not here.
  },
}];

// One item per applicant, from the form or from the demo ZIP. The CV goes to binary.data.
const now = $now.toFormat('yyyy-MM-dd HH:mm');
const out = [];
if ($('Apply (form)').isExecuted) {
  const f = $('Apply (form)').first();
  const key = Object.keys(f.binary || {})[0];
  if (!key) throw new Error('No CV file in the form submission');
  out.push({ json: { name: String(f.json.name || '').trim(), email: String(f.json.email || '').trim(),
    cv_file: f.binary[key].fileName || 'cv.pdf', submitted_at: now, source: 'form' }, binary: { data: f.binary[key] } });
} else {
  // Demo identities: fictional people, emails on example.com (drafts only, never sent)
  const DEMO = {
    'cv-01-rami.pdf': ['Rami Haddad', 'rami.haddad@example.com'], 'cv-02-lina.pdf': ['لينا الخطيب', 'lina.k@example.com'],
    'cv-03-omar.pdf': ['Omar Saleh', 'omar.saleh@example.com'], 'cv-04-hiba.pdf': ['Hiba Nasser', 'hiba.nasser@example.com'],
    'cv-05-yousef.pdf': ['يوسف عبيدات', 'yousef.o@example.com'], 'cv-06-dana.pdf': ['Dana Qasem', 'dana.q@example.com'],
    'cv-07-ahmad.pdf': ['Ahmad Mansour', 'ahmad.mansour@example.com'], 'cv-08-sara.pdf': ['Sara Mansour', 'sara.mansour@example.com'],
  };
  const z = $('Unzip demo CVs').first();
  for (const [, bin] of Object.entries(z.binary || {}).sort((a, b) => (a[1].fileName > b[1].fileName ? 1 : -1))) {
    const [name, email] = DEMO[bin.fileName] || ['Unknown', ''];
    out.push({ json: { name, email, cv_file: bin.fileName, submitted_at: now, source: 'demo' }, binary: { data: bin } });
  }
}
return out;

// Repair the extracted text (ADR-001), give the applicant an anonymous ID, remove the
// identifiers code can find for sure, and build the anonymizer request (ADR-002).
const apps = $('Collect applicants').all();
const texts = $input.all();

// ---- ADR-001: Arabic from PDFs arrives reversed, glyph by glyph, in presentation forms ----
const PRESENTATION = /[\uFB50-\uFDFF\uFE70-\uFEFF]/;
function fixArabicLine(line) {
  if (!PRESENTATION.test(line)) return line;
  const words = line.trim().split(/\s{2,}/).map((w) => {
    const parts = w.split(' ').filter(Boolean);
    const glyphy = parts.filter((p) => [...p].length <= 2).length / parts.length > 0.6;
    return parts.reverse().join(glyphy ? '' : ' ');
  });
  return words.reverse().join(' ').normalize('NFKC').replace(/ ([\u064B-\u0652])/g, '$1'); // no space before diacritics
}
function fixArabic(text) {
  return String(text).split('\n').map(fixArabicLine).join('\n');
}

function shortId(s) { let h = 2166136261; for (const c of s) { h ^= c.codePointAt(0); h = Math.imul(h, 16777619); } return 'C-' + (h >>> 0).toString(36).toUpperCase().slice(0, 6); }
const esc = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

// Removes what code can find for certain: the applicant's own name, email and phone numbers.
function preRedact(text, name, email) {
  let t = text;
  if (email) t = t.replace(new RegExp(esc(email), 'gi'), '[email removed]');
  t = t.replace(/[\w.+-]+@[\w-]+\.[\w.]+/g, '[email removed]');
  t = t.replace(/(\+?\d[\d\s-]{7,}\d)/g, '[phone removed]');
  // n8n's PDF reader can return Arabic words with their letters reversed, so look for both spellings
  for (const part of String(name).split(/\s+/).filter((p) => p.length >= 3)) {
    for (const form of [part, [...part].reverse().join('')]) t = t.replace(new RegExp(esc(form), 'gi'), '[name removed]');
  }
  return t;
}

const system = `You anonymize CVs before they are scored, so the scorer cannot be influenced by who the applicant is.
Remove: name, email, phone, address or city of residence, date of birth and age, gender, nationality, religion, marital status and children, photo mentions, social profile links.
Replace each removed value with [removed]. Make gendered references to the applicant neutral (English: "they"; Arabic: rewrite feminine forms that refer to the applicant into the masculine-generic form, for verbs, job titles and adjectives alike, e.g. "مسوقة رقمية" → "مسوق رقمي", "أدارت" → "أدار", "كتبت" → "كتب").
The text was extracted from a PDF. Arabic words may come out with their letters in reverse order (e.g. "انيل بيطخلا" for "لينا الخطيب", "ةيصخش تامولعم" for "معلومات شخصية"). Restore every Arabic word to its correct spelling and keep the words in reading order. This repair is the only change you may make besides removing identifiers.
Keep EVERYTHING else exactly as written: same words, same numbers, same order, same language. Do not summarize, translate, fix spelling or add anything. Experience, skills, education, company names and dates of jobs stay.
Return JSON: {"anonymized_text": string, "removed": [string]} where "removed" lists the categories you removed.`;

return apps.map((app, i) => {
  const raw = fixArabic(String(texts[i].json.text || ''));
  const arabic = (raw.match(/[\u0600-\u06FF]/g) || []).length;
  const lang = arabic > raw.length * 0.2 ? 'ar' : 'en';
  const pre = preRedact(raw, app.json.name, app.json.email);
  const candidate_id = shortId(app.json.email + '|' + app.json.cv_file + '|' + app.json.submitted_at);
  return { json: { ...app.json, candidate_id, lang, cv_text: raw, cv_chars: raw.length,
    anon_body: {
      messages: [{ role: 'system', content: system }, { role: 'user', content: pre }] } } };
});

// Reads the model's answer (Gemini or OpenAI shape) and passes it on in one shape.
return $input.all().map((i) => {
  const j = i.json;
  let t;
  const parts = j.content?.parts || j.candidates?.[0]?.content?.parts;
  if (Array.isArray(parts)) t = parts.filter((p) => !p.thought && typeof p.text === 'string').map((p) => p.text).join('');
  else t = j.output_text ?? j.text ?? j.content;
  if (typeof t !== 'string') t = JSON.stringify(t ?? '');
  t = t.trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');
  return { json: { choices: [{ message: { content: t } }] }, pairedItem: i.pairedItem };
});

// ADR-002: check the anonymizer's output in code before the scorer sees anything.
// If an identifier slipped through, code removes it and the row is flagged.
const cfg = $('Config').first().json;
const apps = $('Read CV').all();
const res = $input.all();

const esc = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const LEAK_PATTERNS = [
  [/[\w.+-]+@[\w-]+\.[\w.]+/g, 'email'],
  [/\+?\d[\d\s-]{7,}\d/g, 'phone'],
  [/\b(male|female)\b|ذكر|أنثى/gi, 'gender'],
  [/(date of birth|born on|تاريخ الميلاد)\s*:?\s*[\d/.-]{6,}/gi, 'date of birth'],
  [/\b\d{2}\s*(years old)\b|العمر\s*:?\s*\d+/gi, 'age'],
  [/(marital status|الحالة الاجتماعية)\s*:(?![ \t]*\[removed\])[^\n]+/gi, 'marital status'],
  [/(nationality|الجنسية)\s*:(?![ \t]*\[removed\])[^\n]+/gi, 'nationality'],
];

const rubricText = cfg.rubric.map((r) => `- ${r.key} (${r.name}): ${r.guide}`).join('\n');
const system = `You score an anonymized CV against one job. You never see who the applicant is.
Job: ${cfg.job_title}. ${cfg.job_description}
Rubric, each criterion 0-5:
${rubricText}

For EVERY criterion return: key, score (integer 0-5), evidence_quote, reason.
- evidence_quote: copied EXACTLY, character for character, from the CV text: one sentence or fragment, max 25 words. No paraphrasing, no "...", no translation.
- No evidence in the CV → score 0 and evidence_quote "".
- Judge only what is written. Vague claims without specifics ("results-driven", "improved significantly") score at most 2.
- reason: one short sentence, in English.
Return JSON: {"criteria":[{"key","score","evidence_quote","reason"}], "summary": "one sentence"}`;

return apps.map((app, i) => {
  const flags = [];
  let text = '';
  try {
    const parsed = JSON.parse(res[i].json.choices[0].message.content);
    text = String(parsed.anonymized_text || '');
  } catch (e) { /* handled below */ }
  if (text.length < app.json.cv_chars * 0.4) throw new Error(`Anonymizer returned too little text for ${app.json.candidate_id}`);

  // Leak check: the applicant's own name parts, then generic identifiers
  for (const part of String(app.json.name).split(/\s+/).filter((p) => p.length >= 3)) {
    const re = new RegExp(esc(part), 'gi');
    if (re.test(text)) { flags.push('name leaked, removed by code'); text = text.replace(re, '[removed]'); }
  }
  for (const [re, label] of LEAK_PATTERNS) {
    if (text.match(re)) { flags.push(`${label} leaked, removed by code`); text = text.replace(re, '[removed]'); }
  }

  return { json: { candidate_id: app.json.candidate_id, anonymized_text: text, anon_flags: flags,
    score_body: {
      messages: [{ role: 'system', content: system }, { role: 'user', content: text }] } } };
});

// Reads the model's answer (Gemini or OpenAI shape) and passes it on in one shape.
return $input.all().map((i) => {
  const j = i.json;
  let t;
  const parts = j.content?.parts || j.candidates?.[0]?.content?.parts;
  if (Array.isArray(parts)) t = parts.filter((p) => !p.thought && typeof p.text === 'string').map((p) => p.text).join('');
  else t = j.output_text ?? j.text ?? j.content;
  if (typeof t !== 'string') t = JSON.stringify(t ?? '');
  t = t.trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');
  return { json: { choices: [{ message: { content: t } }] }, pairedItem: i.pairedItem };
});

// ADR-003: a score only counts if its quote really is in the (anonymized) CV.
// Totals and the verdict are computed here, in code.
const cfg = $('Config').first().json;
const apps = $('Read CV').all();
const anon = $('Check anonymization').all();
const res = $input.all();

const norm = (s) => String(s).normalize('NFKC').toLowerCase().replace(/[“”"«»]/g, '').replace(/\s+/g, ' ').trim();

return apps.map((app, i) => {
  const a = anon[i].json;
  const flags = [...a.anon_flags];
  let parsed = { criteria: [] };
  try { parsed = JSON.parse(res[i].json.choices[0].message.content); } catch (e) { flags.push('scorer returned no JSON'); }
  const byKey = Object.fromEntries((parsed.criteria || []).map((c) => [c.key, c]));
  const haystack = norm(a.anonymized_text);

  const scores = {}; const evidence = [];
  let unverified = 0;
  for (const r of cfg.rubric) {
    const c = byKey[r.key] || {};
    let score = Math.max(0, Math.min(5, Math.round(Number(c.score) || 0)));
    // The model sometimes misspells the field name (seen: "evidence_year"). Any evidence_* field
    // is accepted, because the quote itself is still checked against the CV below.
    const quoteField = c.evidence_quote ?? Object.entries(c).find(([k]) => k.startsWith('evidence'))?.[1];
    const quote = String(quoteField || '').trim();
    const found = quote && haystack.includes(norm(quote));
    if (score > 0 && !found) { unverified++; flags.push(`${r.key}: quote not in CV, scored 0`); score = 0; }
    scores[r.key] = score;
    evidence.push(`${r.name} ${score}/5: ${found ? '«' + quote + '»' : '(no evidence)'}`);
  }
  const total = Object.values(scores).reduce((s, x) => s + x, 0);
  const verdict = total >= cfg.shortlist_at ? 'shortlist' : total >= cfg.review_at ? 'review' : 'not a fit';

  return { json: {
    candidate_id: app.json.candidate_id, submitted_at: app.json.submitted_at, cv_language: app.json.lang,
    total_25: total, verdict, ...scores, evidence: evidence.join('\n'), flags: flags.join('; '),
    // kept for the next steps, not written to the candidates sheet
    _name: app.json.name, _email: app.json.email, _cv_file: app.json.cv_file,
    _summary: parsed.summary || '', _reasons: (parsed.criteria || []).map((c) => `${c.key}: ${c.reason}`).join('\n'),
    _unverified: unverified,
  } };
});

// For "not a fit" only: ask the model for two concrete, kind improvement points.
// The model sees the anonymized CV and the scores, never the name (ADR-002).
const cfg = $('Config').first().json;
const anon = Object.fromEntries($('Check anonymization').all().map((i) => [i.json.candidate_id, i.json.anonymized_text]));

return $input.all().map(({ json: c }) => {
  const scores = cfg.rubric.map((r) => `${r.name}: ${c[r.key]}/5`).join(', ');
  const language = c.cv_language === 'ar' ? 'Arabic (clear, warm Levantine-friendly Modern Standard Arabic)' : 'English';
  const system = `You write feedback for a job applicant who was not selected for "${cfg.job_title}".
Write in ${language}. Be respectful and specific to THIS CV. No generic advice, no false hope, no mention of scores or AI.
Return JSON: {"points": [two strings, each one concrete thing they could add or improve for this kind of role, max 30 words each], "closing": "one encouraging sentence"}`;
  return { json: { ...c, feedback_body: {
    messages: [{ role: 'system', content: system }, { role: 'user', content: `Scores: ${scores}\nScorer notes:\n${c._reasons}\n\nCV:\n${anon[c.candidate_id] || ''}` }] } } };
});

// Reads the model's answer (Gemini or OpenAI shape) and passes it on in one shape.
return $input.all().map((i) => {
  const j = i.json;
  let t;
  const parts = j.content?.parts || j.candidates?.[0]?.content?.parts;
  if (Array.isArray(parts)) t = parts.filter((p) => !p.thought && typeof p.text === 'string').map((p) => p.text).join('');
  else t = j.output_text ?? j.text ?? j.content;
  if (typeof t !== 'string') t = JSON.stringify(t ?? '');
  t = t.trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');
  return { json: { choices: [{ message: { content: t } }] }, pairedItem: i.pairedItem };
});

// ADR-004: the email becomes a Gmail DRAFT. A person reads it and decides whether to send it.
const cfg = $('Config').first().json;
const reqs = $('Feedback request').all();
const esc = (s) => String(s ?? '').replace(/[&<>"]/g, (ch) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[ch]));

return $input.all().map((r, i) => {
  const c = reqs[i].json;
  let fb = { points: [], closing: '' };
  try { fb = JSON.parse(r.json.choices[0].message.content); } catch (e) { /* empty points → draft says so */ }
  const ar = c.cv_language === 'ar';
  const first = String(c._name || '').split(/\s+/)[0];
  const points = (fb.points || []).slice(0, 2).map((p) => `<li style="margin:0 0 8px;">${esc(p)}</li>`).join('');
  const html = ar
    ? `<div dir="rtl" style="font-family:Tahoma,Arial,sans-serif;font-size:15px;line-height:1.8;color:#1f2937;">
<p>مرحباً ${esc(first)}،</p>
<p>شكراً لتقديمك على وظيفة <b>${esc(cfg.job_title)}</b> وللوقت اللي أعطيته لطلبك.</p>
<p>بعد مراجعة الطلبات، قررنا ما نكمل بطلبك لهالوظيفة. وحابين نشاركك نقطتين ممكن يقووا ملفك بفرص مشابهة:</p>
<ol>${points}</ol>
<p>${esc(fb.closing)}</p>
<p>مع التحية،<br>${esc(cfg.company_ar)}</p></div>`
    : `<div style="font-family:Arial,sans-serif;font-size:15px;line-height:1.7;color:#1f2937;">
<p>Hi ${esc(first)},</p>
<p>Thank you for applying for the <b>${esc(cfg.job_title)}</b> role, and for the time you put into your application.</p>
<p>We've decided not to move forward with your application for this role. Here are two things that could strengthen your profile for similar roles:</p>
<ol>${points}</ol>
<p>${esc(fb.closing)}</p>
<p>Best regards,<br>${esc(cfg.company_en)}</p></div>`;
  return { json: { to: c._email, candidate_id: c.candidate_id,
    subject: ar ? `بخصوص طلبك لوظيفة ${cfg.job_title}` : `Your application for ${cfg.job_title}`, html } };
});
